#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

# Everything below is relative to the repo root, so the wizard can be
# started from anywhere.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

banner "Put Khair on the internet"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Neon: the database"
say "Khair keeps its tasks and signups in Postgres. Neon gives one away free,"
say "and it is the only database this app will ever need."
printf '\n'
open_url "https://neon.tech"
step "Sign up (GitHub or Google is quickest), then create a project."
note "  Already made one? Open it instead; nothing here creates a second."
step "Call it khair. Any region near the mosque is fine."
step "On the project dashboard, find the connection string."
printf '\n'
warn "Copy the POOLED one. Neon shows a toggle or a checkbox marked"
note "  'Pooled connection' or 'Connection pooling'; its host contains -pooler."
note "  Khair runs on serverless functions, each of which opens its own pool,"
note "  and the unpooled host runs out of connections once a few people are"
note "  on the page at once."
printf '\n'
note "It looks like: postgresql://user:pass@ep-xxx-pooler.region.aws.neon.tech/neondb?sslmode=require"
printf '\n'
ask_secret DATABASE_URL "Paste the pooled connection string:"

if [[ -z "$DATABASE_URL" ]]; then
  warn "Nothing pasted, so there is nothing to deploy against. Re-run when you have it."
  exit 1
fi
case "$DATABASE_URL" in
  *-pooler*) : ;;
  *) warn "That host has no -pooler in it. Khair will work until it is busy, then stop."
     confirm "Use it anyway?" || { say "Re-run the wizard with the pooled string."; exit 1; } ;;
esac
case "$DATABASE_URL" in
  *sslmode=*) : ;;
  *) DATABASE_URL="${DATABASE_URL}?sslmode=require"
     note "Added ?sslmode=require, which Neon needs." ;;
esac
write_env DATABASE_URL "$DATABASE_URL"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The two secrets"
say "One password for the admin view, and one secret so that only Vercel's"
say "scheduler can trigger the nightly deletion of old records."
printf '\n'
step "Pick an admin password you can tell the person who publishes tasks."
note "  It is the only credential in the whole app. Nothing is typed in by"
note "  volunteers, so make it long rather than clever."
ask_secret ADMIN_PASSWORD "Admin password:"

case "$(printf '%s' "$ADMIN_PASSWORD" | tr '[:upper:]' '[:lower:]')" in
  ""|change-me|changeme|password)
    warn "That is the placeholder the app ships with, and it refuses to sign"
    warn "anybody in with it in production. Choose another."
    ask_secret ADMIN_PASSWORD "Admin password:"
    ;;
esac
write_env ADMIN_PASSWORD "$ADMIN_PASSWORD"

CRON_SECRET=$(_existing CRON_SECRET || true)
if [[ -z "$CRON_SECRET" ]]; then
  CRON_SECRET=$(openssl rand -base64 32 2>/dev/null || head -c 32 /dev/urandom | base64)
  say "Generated a cron secret for you; nobody needs to remember it."
fi
write_env CRON_SECRET "$CRON_SECRET"
printf '\n'
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The mosque's own details"
say "These appear on the public pages, so they are worth getting right."
printf '\n'
ask MOSQUE_NAME "Mosque name (shown beside the wordmark):"
[[ -n "$MOSQUE_NAME" ]] || MOSQUE_NAME="Al-Madinah Center"
write_env MOSQUE_NAME "$MOSQUE_NAME"

say ""
note "Times are grouped by the mosque's own day, not the server's."
ask APP_TIMEZONE "Timezone [America/Toronto]:"
[[ -n "$APP_TIMEZONE" ]] || APP_TIMEZONE="America/Toronto"
write_env APP_TIMEZONE "$APP_TIMEZONE"

note "Local numbers typed without a country code are read as this country."
ask DEFAULT_PHONE_COUNTRY "Phone country [CA]:"
[[ -n "$DEFAULT_PHONE_COUNTRY" ]] || DEFAULT_PHONE_COUNTRY="CA"
write_env DEFAULT_PHONE_COUNTRY "$DEFAULT_PHONE_COUNTRY"

write_env RETENTION_MONTHS "$(_existing RETENTION_MONTHS || echo 6)"
write_env EARLY_ACCESS_HOURS "$(_existing EARLY_ACCESS_HOURS || echo 24)"
write_env UNDO_WINDOW_MINUTES "$(_existing UNDO_WINDOW_MINUTES || echo 30)"
printf '\n'
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Build the tables in Neon"
say "The database is empty. This creates its tables, and nothing else:"
say "no sample data, no demo volunteers."
printf '\n'
note "It runs through Docker, because this machine has no Node of its own."
printf '\n'
if confirm "Run the migrations against Neon now?"; then
  if MSYS_NO_PATHCONV=1 docker compose run --rm --no-deps \
      -e DATABASE_URL="$DATABASE_URL" web npm run migrate; then
    printf '\n'
    say "Tables are in place."
  else
    printf '\n'
    warn "That did not work. The usual causes are Docker not running, or a"
    warn "connection string that is missing ?sslmode=require."
    SKIPPED+=("database migrations: docker compose run --rm -e DATABASE_URL=... web npm run migrate")
  fi
else
  SKIPPED+=("database migrations (the app cannot work until these run)")
fi
printf '\n'
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub: somewhere for the code to live"
say "Vercel deploys from a repository, and every later push republishes the"
say "site. This also means the mosque's code is backed up somewhere other"
say "than one laptop."
printf '\n'
open_url "https://github.com/new"
step "Name it khair."
step "Choose Private unless you want the code public."
step "Add NO readme, NO .gitignore and NO licence: this repo already has them."
step "Create the repository, then copy the HTTPS URL it shows you."
printf '\n'
note "It looks like: https://github.com/yourname/khair.git"
printf '\n'
ask GITHUB_REMOTE "Paste the repository URL:"

if [[ -n "$GITHUB_REMOTE" ]]; then
  if git remote get-url origin >/dev/null 2>&1; then
    git remote set-url origin "$GITHUB_REMOTE"
  else
    git remote add origin "$GITHUB_REMOTE"
  fi
  say ""
  say "Pushing. A sign-in window may open: that is GitHub asking who you are."
  BRANCH=$(git branch --show-current)
  if git push -u origin "$BRANCH"; then
    say ""
    printf '  %s✓%s pushed %s to origin\n' "$GREEN" "$RESET" "$BRANCH"
  else
    warn "The push failed. Fix the sign-in, then: git push -u origin $BRANCH"
    SKIPPED+=("git push -u origin $BRANCH")
  fi
else
  SKIPPED+=("create the GitHub repo and push to it")
fi
printf '\n'
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel: import the repository"
say "Vercel's free Hobby plan runs this app and its nightly cleanup at no"
say "cost. It will detect Next.js on its own: change none of the build"
say "settings it offers."
printf '\n'
open_url "https://vercel.com/new"
step "Sign in with GitHub."
step "Find khair in the list and click Import."
step "Leave Framework, Build Command and Output Directory exactly as found."
step "Click Deploy, and let it finish."
printf '\n'
warn "This first deploy will build, but the site will not work yet: it has no"
note "  database or password until the next stage. That is expected."
printf '\n'
pause "Press Enter once the first deploy has finished"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Vercel: the settings the app runs on"
say "Everything the app needs, written to .env.vercel so you can paste it in"
say "one go rather than typing eleven rows by hand."
printf '\n'

{
  printf 'DATABASE_URL=%s\n' "$DATABASE_URL"
  printf 'ADMIN_PASSWORD=%s\n' "$ADMIN_PASSWORD"
  printf 'CRON_SECRET=%s\n' "$CRON_SECRET"
  printf 'MOSQUE_NAME=%s\n' "$MOSQUE_NAME"
  printf 'APP_TIMEZONE=%s\n' "$APP_TIMEZONE"
  printf 'DEFAULT_PHONE_COUNTRY=%s\n' "$DEFAULT_PHONE_COUNTRY"
  printf 'RETENTION_MONTHS=%s\n' "$(_existing RETENTION_MONTHS || echo 6)"
  printf 'EARLY_ACCESS_HOURS=%s\n' "$(_existing EARLY_ACCESS_HOURS || echo 24)"
  printf 'UNDO_WINDOW_MINUTES=%s\n' "$(_existing UNDO_WINDOW_MINUTES || echo 30)"
} > .env.vercel
printf '  %s✓ wrote%s .env.vercel  %s(gitignored, holds real secrets)%s\n' \
  "$GREEN" "$RESET" "$DIM" "$RESET"
printf '\n'
open_url "https://vercel.com/dashboard"
step "Open the khair project, then Settings, then Environment Variables."
step "Use the bulk paste or import option and paste the whole of .env.vercel."
step "Leave the environment set to Production."
step "Save."
printf '\n'
note "CRON_SECRET is special: with it set, Vercel's scheduler sends it as a"
note "bearer token to /api/cron/purge, which is how the nightly deletion of"
note "records older than your retention window authorises itself. Without it"
note "that endpoint stays closed, which is the safe way round."
printf '\n'
step "Now go to Deployments, open the newest one, and Redeploy it."
note "  Environment variables only reach a build that happens after them."
printf '\n'
pause "Press Enter once the redeploy has finished"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check it is actually live"
say "Vercel gives the project a URL like khair-xxxx.vercel.app, shown at the"
say "top of the project page."
printf '\n'
ask APP_ORIGIN "Paste the live URL (https://...):"
APP_ORIGIN="${APP_ORIGIN%/}"
write_env APP_ORIGIN "$APP_ORIGIN"

if [[ -n "$APP_ORIGIN" ]]; then
  printf '\n'
  say "Checking..."
  CODE=$(curl -s -o /dev/null -w '%{http_code}' "$APP_ORIGIN/en" || echo "000")
  if [[ "$CODE" == "200" ]]; then
    printf '  %s✓%s the public list answers\n' "$GREEN" "$RESET"
  else
    warn "the public list answered $CODE, not 200"
    note "  502 or 500 usually means DATABASE_URL is missing or unpooled."
    note "  404 usually means the redeploy has not finished."
  fi
  CODE=$(curl -s -o /dev/null -w '%{http_code}' "$APP_ORIGIN/admin" || echo "000")
  [[ "$CODE" == "200" ]] \
    && printf '  %s✓%s the admin sign-in answers\n' "$GREEN" "$RESET" \
    || warn "the admin page answered $CODE"
  printf '\n'
  warn "One more variable, now that the URL exists:"
  step "Add APP_ORIGIN=$APP_ORIGIN in Settings, Environment Variables."
  note "  It is what the calendar entries volunteers save link back to."
  step "Redeploy once more."
  printf '\n'
  pause "Press Enter when that is done"
else
  SKIPPED+=("APP_ORIGIN on Vercel (calendar links will guess the host)")
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "The poster"
if [[ -n "$APP_ORIGIN" ]]; then
  say "A QR code pointing at $APP_ORIGIN, on an A4 sheet, in three languages."
  printf '\n'
  if MOSQUE_NAME="$MOSQUE_NAME" ./scripts/poster.sh "$APP_ORIGIN"; then
    printf '\n'
    open_url "poster/khair-poster.html"
    step "Print it with Ctrl-P. Scale 100%, no headers or footers."
    step "Scan it with your own phone before putting it on a wall."
  else
    warn "The poster did not generate. Run it yourself later:"
    note "  ./scripts/poster.sh $APP_ORIGIN"
    SKIPPED+=("the printable poster: ./scripts/poster.sh $APP_ORIGIN")
  fi
else
  warn "No live URL, so there is nothing to point a QR code at."
  SKIPPED+=("the printable poster: ./scripts/poster.sh <live-url>")
fi
printf '\n'
pause "Press Enter for the last word"

finish || true
printf '  %sBefore you tell anybody about it:%s\n' "$BOLD" "$RESET"
note "  - Sign in at $APP_ORIGIN/admin and publish one real task."
note "  - Scan the poster yourself and claim that task, to see the whole path."
note "  - The nightly cleanup runs once a day on the free plan. That is enough:"
note "    retention is measured in months."
printf '\n'
printf '  %sLater:%s a git push redeploys. Secrets live only on Vercel and in\n' "$BOLD" "$RESET"
printf '  your gitignored .env files, never in the repository.\n\n'
